mapper.select:
select id, user_id AS userId, report_type AS reportType, report_date AS reportDate, content, summary, create_dept AS createDept, create_by AS createBy, create_time AS createTime, update_by AS updateBy, update_time AS updateTime, deleted_flag AS deletedFlag, tenant_id AS tenantId from mes_rec_report
deleted_flag = 0 and user_id = #{param.userId}
and id = #{param.id}
and report_type = #{param.reportType}
and report_date >= #{param.beginReportDate}
and #{param.endReportDate} > report_date
order by report_date desc
